    export type LogActionArgs<ExtArgs extends $Extensions.InternalArgs = $Extensions.DefaultArgs> = LogActionDefaultArgs<ExtArgs>

  /**
   * Batch Payload for updateMany & deleteMany & createMany
   */

  export type BatchPayload = {
    count: number
  }

  /**
   * DMMF
   */
  export const dmmf: runtime.BaseDMMF
